"use client";

import { loadFont } from "@remotion/google-fonts/Nunito";
import type React from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type ChunkStackElementId,
  chunkStackTimeline,
  DEFAULT_TEXT,
  wordsOf,
} from "./timeline";

const nunito = loadFont("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

export interface ChunkStackProps {
  text?: string;
  highlight?: string;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the words. Load it yourself; Nunito by default. */
  fontFamily?: string;
  fontWeight?: number;
  /** Frames between words as they drop into the stack. */
  stagger?: number;
  /** Size of the words, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the rise, the gaps opening and single word
   * drops, by the ids in `./timeline`. Frames on the scene timeline, after
   * `delay` and `speed`.
   */
  timing?: Timing<ChunkStackElementId>;
}

const THEMES = {
  dark: {
    bg: "#133A24",
    ink: "#EAF7EC",
    accent: "#FFD23F",
    pillInk: "#133A24",
  },
  light: {
    bg: "#FFD23F",
    ink: "#133A24",
    accent: "#FFFFFF",
    pillInk: "#133A24",
  },
} as const;

const FONT_PX = 200;
const TRACK = -0.025;
const LEAD = 0.98;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN_OUT = Easing.bezier(0.65, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  run: number[];
  runW: number;
  words: number[];
  space: number;
  asc: number;
  desc: number;
  xh: number;
}

function measure(
  words: string[],
  fontFamily: string,
  fontWeight: number,
): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("chunk-stack: no 2d context");
  ctx.font = `${fontWeight} ${FONT_PX}px "${fontFamily}"`;
  const w = (s: string) =>
    ctx.measureText(s).width / FONT_PX +
    TRACK * Math.max(0, Array.from(s).length - 1);
  const run: number[] = [];
  let prefix = "";
  for (const word of words) {
    run.push(prefix ? w(prefix) + TRACK : 0);
    prefix += word;
  }
  const fm = ctx.measureText("Hg");
  return {
    run,
    runW: w(prefix),
    words: words.map(w),
    space: ctx.measureText(" ").width / FONT_PX,
    asc: fm.fontBoundingBoxAscent / FONT_PX,
    desc: fm.fontBoundingBoxDescent / FONT_PX,
    xh: ctx.measureText("x").actualBoundingBoxAscent / FONT_PX,
  };
}

function useMetrics(words: string[], fontFamily: string, fontWeight: number) {
  const key = words.join(" ");
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [handle] = useState(() => delayRender("chunk-stack: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      nunito.waitUntilDone(),
      document.fonts.load(`${fontWeight} 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setMetrics(measure(key.split(" "), fontFamily, fontWeight));
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle, fontFamily, fontWeight]);
  return metrics;
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function impact(u: number) {
  if (u < 0) return 0;
  return Math.exp(-u / 3.4) * Math.cos(u * 0.6);
}

export function ChunkStack(props: ChunkStackProps) {
  const {
    text = DEFAULT_TEXT,
    highlight = "making",
    accent,
    ink,
    background,
    fontFamily = nunito.fontFamily,
    fontWeight = 500,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    chunkStackTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const bg = background ?? c.bg;
  const pill = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const words = useMemo(() => wordsOf(text), [text]);
  const m = useMetrics(words, fontFamily, fontWeight);

  if (!m || words.length === 0) {
    return <div style={{ position: "absolute", inset: 0, background: bg }} />;
  }

  const n = words.length;
  const gapOpen = m.space * 1.35;
  const spacedW = m.runW + gapOpen * (n - 1);
  const riseEl = tl.get("rise");
  const open = tl.get("open");
  const openAll = interpolate(t, [open.start, open.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IN_OUT,
  });
  const lineSize = Math.min(
    (W * 0.9) / (m.runW + (spacedW - m.runW) * openAll),
    H * 0.2,
  );
  const maxWord = Math.max(...m.words);
  const stackSize = Math.min(
    (W * 0.82) / maxWord,
    (H * 0.84) / (LEAD * (n - 1) + m.xh + 0.32),
    H * 0.3,
  );
  const R = Math.max(lineSize, stackSize);
  const lh = R * 1.4;
  const bo = (lh - (m.asc + m.desc) * R) / 2 + m.asc * R;

  const lineBase = H / 2 + (m.xh * lineSize) / 2;
  const stackH = (LEAD * (n - 1) + m.xh) * stackSize;
  const stackTop = (H - stackH) / 2 + m.xh * stackSize;

  const rise = interpolate(t, [riseEl.start, riseEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const opens = Array.from({ length: n }, (_, k) =>
    k === 0
      ? 0
      : interpolate(
          t,
          [
            open.start + (k - 1) * open.beat("gap"),
            open.start + (k - 1) * open.beat("gap") + open.beat("each"),
          ],
          [0, 1],
          { ...CLAMP, easing: EASE_OUT },
        ),
  );
  let shift = 0;
  const lineX: number[] = [];
  for (let k = 0; k < n; k++) {
    shift += opens[k] * gapOpen;
    lineX.push(m.run[k] + shift);
  }
  const curW = m.runW + shift;
  const lineLeft = (W - curW * lineSize) / 2;

  const hlIndex = words.findIndex(
    (w) =>
      w.replace(/[^\p{L}\p{N}]/gu, "") ===
      highlight.replace(/[^\p{L}\p{N}]/gu, ""),
  );

  const nodes: React.ReactNode[] = [];
  let pillNode: React.ReactNode = null;
  for (let k = 0; k < n; k++) {
    const drop = tl.get(`drop:${k}`);
    const start = drop.start;
    const land = drop.beat("land");
    const fallAt = start + drop.beat("fall");
    const dv = interpolate(t, [fallAt, fallAt + drop.beat("fallLen")], [0, 1], {
      ...CLAMP,
      easing: EASE_IN_OUT,
    });
    const d = interpolate(
      t,
      [start + drop.beat("slide"), start + land],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_IN_OUT,
      },
    );
    const x0 = lineLeft + lineX[k] * lineSize + (m.words[k] * lineSize) / 2;
    const y0 = lineBase;
    const x1 = W / 2;
    const y1 = stackTop + k * LEAD * stackSize;
    const size = lineSize + (stackSize - lineSize) * d;
    // Layout rounds a box and a baseline to whole pixels, so a word carried
    // by `left`/`top` clicks along. Each word is laid out on its stack line
    // and the whole trip there is a transform. While the sentence sits still
    // as one line, it keeps the line's own layout, which is where it rested.
    const parked = rise === 1 && openAll === 0 && d === 0 && dv === 0;
    const ax = parked ? x0 : x1;
    const ay = parked ? y0 : y1;
    const dx = parked ? 0 : (x0 - x1) * (1 - d);
    const q = impact(t - start - land);
    const squashing =
      Math.abs(impact(t - start - land + speed) - q) * lh > 1e-2 ||
      Math.abs(q - impact(t - start - land - speed)) * lh > 1e-2;
    const sx = 1 + 0.08 * q;
    const sy = 1 - 0.12 * q;
    const s = size / R;
    const wpx = m.words[k] * R;
    const risePx = (1 - rise) * lineSize * 1.3;
    const dy = parked ? 0 : (y0 - y1) * (1 - dv) + risePx;
    const travel =
      Math.abs(dx) < 1e-3 && Math.abs(dy) < 1e-3
        ? ""
        : `translate(${dx}px, ${dy}px) `;
    const moving =
      midway(rise) || midway(openAll) || midway(dv) || midway(d) || squashing;

    if (k === hlIndex) {
      const pp = interpolate(
        t,
        [start + drop.beat("pill"), start + drop.beat("pillEnd")],
        [0, 1],
        { ...CLAMP, easing: EASE_OUT },
      );
      if (pp > 0) {
        const padX = 0.2 * stackSize;
        const pw = m.words[k] * stackSize + padX * 2;
        const ph = (m.xh + 0.62) * stackSize;
        const top = y1 - (m.xh + 0.3) * stackSize;
        pillNode = (
          <div
            key="pill"
            style={{
              position: "absolute",
              left: x1 - pw / 2,
              top,
              width: pw,
              height: ph,
              borderRadius: ph * 0.34,
              background: pill,
              opacity: pp,
              transform: `scale(${(0.9 + 0.1 * pp) * sx}, ${(0.7 + 0.3 * pp) * sy})`,
              transformOrigin: `50% ${((m.xh + 0.3) * stackSize).toFixed(1)}px`,
            }}
          />
        );
      }
    }

    const hlOn =
      k === hlIndex
        ? interpolate(
            t,
            [start + drop.beat("ink"), start + drop.beat("inkEnd")],
            [0, 1],
            CLAMP,
          )
        : 0;
    nodes.push(
      <div
        key={`w${k}`}
        style={{
          position: "absolute",
          left: ax - wpx / 2,
          top: ay - bo,
          width: wpx,
          height: lh,
          fontFamily,
          fontWeight,
          fontSize: R,
          lineHeight: `${lh}px`,
          letterSpacing: `${TRACK}em`,
          whiteSpace: "pre",
          color: hlOn > 0.5 ? c.pillInk : fg,
          transform: `${travel}scale(${(s * sx).toFixed(4)}, ${(s * sy).toFixed(4)})${glide(moving)}`,
          transformOrigin: `50% ${bo.toFixed(1)}px`,
        }}
      >
        {words[k]}
      </div>,
    );
  }

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            clipPath:
              t < riseEl.end
                ? `inset(0 0 ${(H - lineBase - m.desc * lineSize * 0.9).toFixed(1)}px 0)`
                : undefined,
          }}
        >
          {pillNode}
          {nodes}
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The sentence rising in as one line, the gaps between its words opening,
// and each word dropping into the stack. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

export type ChunkStackElementId = "rise" | "open" | `drop:${number}`;

export interface ChunkStackTimingProps {
  text?: string;
  stagger?: number;
}

export const DEFAULT_TEXT = "learn motion by making it";
/** Frames between words as they drop, by default. */
export const DROP_GAP = 4;

/** The words of the sentence, as the component draws them. */
export const wordsOf = (text: string) =>
  text.trim().split(/\s+/).filter(Boolean);

const RISE_LEN = 16;
const OPEN_AT = 26;
const OPEN_GAP = 3;
const OPEN_LEN = 14;
const DROP_AT = 50;
/** The words start falling 2 frames apart, whatever the stagger. */
const FALL_GAP = 2;
const FALL_LEN = 12;
const SLIDE_AT = 6;
const DROP_LEN = 22;

// The open's `gap` beat is the time between two gaps opening and `each` how
// long one gap takes. A drop starts at its slide's slot: `fall` (possibly
// negative) is when the word starts falling, `slide` when it starts across,
// `land` when it lands and bounces; the highlight pill grows from `pill` to
// `pillEnd` and the word turns from `ink` to `inkEnd`. Each drop follows the
// one before; the first follows the open, the open follows the rise.
export const chunkStackTimeline = defineTimeline<
  ChunkStackElementId,
  ChunkStackTimingProps
>(({ text = DEFAULT_TEXT, stagger = DROP_GAP }) => {
  const words = wordsOf(text);
  const n = words.length;
  const elements: TimelineElement<ChunkStackElementId>[] = [
    { id: "rise", lane: "Line", label: "rise", start: 0, length: RISE_LEN },
    {
      id: "open",
      lane: "Line",
      label: "open gaps",
      start: OPEN_AT,
      length: (n - 2) * OPEN_GAP + OPEN_LEN,
      follows: "rise",
      beats: { gap: OPEN_GAP, each: OPEN_LEN },
    },
  ];
  words.forEach((word, k) => {
    elements.push({
      id: `drop:${k}`,
      lane: "Stack",
      label: word,
      start: DROP_AT + k * stagger,
      length: DROP_LEN,
      follows: k > 0 ? `drop:${k - 1}` : "open",
      beats: {
        fall: k * FALL_GAP - k * stagger,
        fallLen: FALL_LEN,
        slide: SLIDE_AT,
        land: DROP_LEN,
        pill: DROP_LEN - 2,
        pillEnd: DROP_LEN + 10,
        ink: DROP_LEN - 1,
        inkEnd: DROP_LEN + 6,
      },
    });
  });
  return elements;
});
